  "Bratteste tak (grader)": "Stačiausias stogas (laipsniais)",
  "Lagrede takresultater": "I\u0161saugoti stogo rezultatai",
  "Gi oppsettet et navn og lagre det. Trykk på navnet senere for å legge samme platelengder og håndjusteringer på bygget igjen.": "Suteikite nustatymui pavadinim\u0105 ir i\u0161saugokite. V\u0117liau spustel\u0117j\u0119 pavadinim\u0105 grąžinsite tuos pačius lak\u0161t\u0173 ilgius ir koregavimus.",
  "{0} plater er lengre enn transportgrensa på {1} mm (lengste {2} mm). Bjelkene gir ingen skjøt før der — tast platelengder selv hvis de må deles, eller bestill spesialtransport.": "{0} lakštų yra ilgesni nei {1} mm transporto riba (ilgiausias {2} mm). Sijos anksčiau sandūros nesuteikia — įveskite lakštų ilgius patys, jei juos reikia dalyti, arba użsisakykite specialų transportą.",
  "Tom = platene deles av bjelkene: én skjøt på hver ås, ingen andre steder. Skriver du tall — f.eks. «6000, 5500, 6000, 5000» — blir platene akkurat de lengdene etter hverandre, fra gesimsen og opp. Siste lengde gjentas hvis fallet er lengre, og tallene er DEKNING: overlappen kommer i tillegg.": "Tuščia = lakštus dalija sijos: viena sandūra ant kiekvienos gegnės, niekur kitur. Jei įvesite skaičius — pvz., „6000, 5500, 6000, 5000“ — lakštai bus būtent tokio ilgio vienas po kito, nuo karnizo aukštyn. Paskutinis ilgis kartojasi, jei nuolydis ilgesnis, o skaičiai yra DENGIMAS: użlaida pridedama papildomai.",
  "Ingen åser på tvers er modellert i takplanet. Da er det ingenting å skjøte i, og hvert fall blir én plate. Taster du platelengder selv, står de som du skriver dem — men skjøtene er IKKE kontrollert mot stål. Sjekk mot arbeidstegning, eller roter takflata hvis platene skal ligge den andre veien.": "Stogo plokštumoje neatvaizduota skersinių gegnių. Nėra prie ko jungti, todėl kiekvieną nuolydį dengia vienas lakštas. Jei ilgius įvesite patys, jie liks tokie, kokius įvedate — bet sandūros NĖRA patikrintos su plienu. Patikrinkite darbo brėżinį arba pasukite stogo plokštumą.",
  "Åser på tvers, målt opp fallet: {0} mm ({1} av {2} takflater har åser). Du har tastet platelengder selv — dine tall vinner, og skjøtene ligger der du sier.": "Skersinės gegnės, matuojant aukštyn nuolydžiu: {0} mm ({1} iš {2} stogo plokštumų turi gegnes). Lakštų ilgius įvedėte patys — Jūsų skaičiai laimi, o sandūros lieka ten, kur nurodote.",
  "Åser på tvers, målt opp fallet: {0} mm ({1} av {2} takflater har åser). Platene skjøtes på hver av dem — én skjøt per ås, ingen andre steder.": "Skersinės gegnės, matuojant aukštyn nuolydžiu: {0} mm ({1} iš {2} stogo plokštumų turi gegnes). Lakštai jungiami ant kiekvienos iš jų — viena sandūra vienai gegnei, niekur kitur.",
  "Transportgrense (mm) — varsler, deler ikke": "Transporto riba (mm) — įspėja, nedalija",
  "Ingen åser på tvers er modellert i takplanet. Platelengdene dine står som du skriver dem, men skjøtene er IKKE kontrollert mot stål — sjekk mot arbeidstegning, eller roter takflata hvis platene skal ligge den andre veien.": "Stogo plok\u0161tumoje neatvaizduota skersini\u0173 gegni\u0173. J\u016bs\u0173 lak\u0161t\u0173 ilgiai lieka tokie, kokius \u012fvedate, bet sand\u016bros N\u0116RA patikrintos su plienu \u2014 patikrinkite darbo br\u0117\u017cin\u012f arba pasukite stogo plok\u0161tum\u0105.",
  "Åser på tvers, målt opp fallet: {0} mm ({1} av {2} takflater har åser). Snapping er slått AV — skjøtene ligger der du sier.": "Skersin\u0117s gegn\u0117s, matuojant auk\u0161tyn nuolydžiu: {0} mm ({1} i\u0161 {2} stogo plok\u0161tum\u0173 turi gegnes). Pritraukimas I\u0160JUNGTAS \u2014 sand\u016bros lieka ten, kur nurodote.",
  "Åser på tvers, målt opp fallet: {0} mm ({1} av {2} takflater har åser). Skjøtene flyttes til nærmeste ås.": "Skersin\u0117s gegn\u0117s, matuojant auk\u0161tyn nuolydžiu: {0} mm ({1} i\u0161 {2} stogo plok\u0161tum\u0173 turi gegnes). Sand\u016bros perkeliamos prie artimiausios gegn\u0117s.",
  "Taket er generert og følger stålet. {0} håndjusteringer ligger OPPÅ det regnede — de er grunnen hvis platelengdene ikke er de du taster.": "Stogas sugeneruotas ir seka plien\u0105. {0} rankiniai koregavimai guli ANT apskai\u010diuoto i\u0161d\u0117stymo \u2014 d\u0117l j\u0173 lak\u0161t\u0173 ilgiai n\u0117ra tokie, kokius \u012fvedate.",
  "Nullstill justeringer ({0})": "Atstatyti koregavimus ({0})",
