  "Takflata er rotert 90°. Platene ligger nå PÅ TVERS av fallet, og en endeskjøt får vann stående i overlappen. Roter tilbake hvis platene skal følge vannveien.": "Stogo plok\u0161tuma pasukta 90\u00b0. Lak\u0161tai dabar guli SKERSAI nuolydžio, o galin\u0117je sand\u016broje susilaikys vanduo. Pasukite atgal, jei lak\u0161tai turi eiti pagal nuolyd\u012f.",
  "Ingen åser på tvers inne i fallet ({0} mm). Da er det ingenting å skru en endeskjøt i, og fallet må dekkes av ÉN plate. Roter takflata hvis platene skal ligge den andre veien.": "Nuolydyje n\u0117ra skersini\u0173 gegni\u0173 ({0} mm). N\u0117ra prie ko prisukti galin\u0117s sand\u016bros, tod\u0117l nuolyd\u012f turi dengti VIENAS lak\u0161tas. Pasukite stogo plok\u0161tum\u0105, jei lak\u0161tai tur\u0117t\u0173 gul\u0117ti kitaip.",
  "Åser på tvers, målt opp fallet: {0} mm. Snapping er slått AV — skjøtene ligger der du sier.": "Skersin\u0117s gegn\u0117s, matuojant auk\u0161tyn nuolydžiu: {0} mm. Pritraukimas I\u0160JUNGTAS \u2014 sand\u016bros lieka ten, kur nurodote.",
