  "Velg elementer med shift-klikk eller shift-dra, åpne Grupper (i Bygg Info) og lagre utvalget med navn. Trykk på en lagret gruppe for å hente den fram: kameraet flyr dit, og på kontoret skjules alt annet. Vis alle henter tilbake resten.": "Pažymėkite elementus shift-spustelėjimu arba shift-vilkimu, atidarykite Grupes (Pastato info) ir išsaugokite pažymėjimą su pavadinimu. Spustelėkite išsaugotą grupę — kamera nuskris prie jos, o biure visa kita bus paslėpta. Rodyti viską grąžina likusius.",
