  // ---------- Startskjerm ----------
  "Åpne en IFC-modell (BIM) direkte i nettleseren – på mobil eller PC. Naviger i 3D, trykk på elementer for info, mål, snitt og legg inn markeringer.": "Atidarykite IFC modelį (BIM) tiesiai naršyklėje – telefone ar kompiuteryje. Naršykite 3D, spustelėkite elementus informacijai, matuokite, pjaukite ir dėkite žymeklius.",
  "Velg IFC-fil": "Pasirinkti IFC failą",
  "… eller dra fila rett inn i vinduet. Ligger modellen i OneDrive med skyikon (bare på nett), bruk Biblioteket – eller høyreklikk fila i Utforsker → «Behold alltid på denne enheten».": "… arba vilkite failą tiesiai į langą. Jei modelis yra „OneDrive“ su debesies ženkliuku (tik internete), naudokite biblioteką – arba spustelėkite failą dešiniu mygtuku naršyklėje → „Visada laikyti šiame įrenginyje“.",
