  "Feltene over leses fra oppsett.json i SharePoint-mappa med modellene. Et felt som mangler er ikke en feil – da brukes standardverdien i koden – men da har du heller ikke kontroll på tallet fra fila. Merk at kopien i prosjektmappa ikke er den verktøyet leser.": "Aukščiau esantys laukai skaitomi iš oppsett.json „SharePoint“ aplanke su modeliais. Trūkstamas laukas nėra klaida – naudojama numatytoji kodo reikšmė – bet tada nekontroliuojate failo reikšmės. Atkreipkite dėmesį, kad projekto aplanko kopija nėra ta, kurią skaito įrankis.",
