  "Umulig volum (stk)": "Neįmanomas tūris (vnt.)",
  "Nettleseren fikk ingen fil ut av det du slapp. Det skjer når fila bare finnes i skya (OneDrive «bare på nett»), eller når den dras fra Outlook, Teams, en zip-mappe eller en nettside. Høyreklikk fila i Utforsker → «Behold alltid på denne enheten» og prøv igjen — eller bruk Velg IFC-fil.": "Naršyklė negavo failo iš to, ką numetėte. Taip nutinka, kai failas yra tik debesyje („OneDrive tik internete“) arba kai jis velkamas iš „Outlook“, „Teams“, zip aplanko ar tinklalapio. Dešiniuoju pelės mygtuku spustelėkite failą naršyklėje → „Visada laikyti šiame įrenginyje“ ir bandykite dar kartą – arba naudokite Pasirinkti IFC failą.",
