  "{0} element er skjult enkeltvis. «Vis alle» henter dem fram.": "Paslėpta po vieną: {0}. „Rodyti visus“ juos grąžina.",
  // 🏗 Størrelsesdialogen: het «Nytt prosjekt» og ble lest som at et nytt
