  "Dette oppretter ingenting — opplastingen går til prosjektet du skrev inn. Spørsmålet kommer én gang per prosjekt, og svaret lagres på prosjektet.": "Tai nieko nesukuria — įkėlimas keliauja į jūsų įvestą projektą. Klausimas užduodamas kartą per projektą, o atsakymas išsaugomas projekte.",
  "Opplastingsnøkkelen ble ikke godtatt. Prøv igjen, så spør den om nøkkelen på nytt.": "Įkėlimo raktas nepriimtas. Bandykite dar kartą — rakto bus paprašyta iš naujo.",
