  "Lagres i SharePoint — alle med tilgang ser det samme.": "Įrašoma į SharePoint — visi, turintys prieigą, mato tą patį.",
  "Får ikke kontakt med SharePoint. Lagres bare på denne maskinen inntil videre.": "Nepavyksta pasiekti SharePoint. Kol kas įrašoma tik šiame kompiuteryje.",
  "Lagres bare på denne maskinen. Trykk på den røde prikken øverst til høyre og logg inn for å dele med de andre.": "Įrašoma tik šiame kompiuteryje. Paspauskite raudoną tašką viršuje dešinėje ir prisijunkite, kad pasidalintumėte su kitais.",
