  "Ingen område-firkanter i modellen ennå. Tegn utsparingene med Markering → Firkant først — bare de du huker av her blir åpninger.": "Modelyje dar nėra ploto stačiakampių. Pirmiausia nubrėžkite angas: Žyma → Stačiakampis — tik čia pažymėtos taps angomis.",
