  "Dra fra senter og ut — området blir en sirkel": "Vilkite nuo centro į išorę — plotas taps apskritimu",
  "Dra fra hjørne til hjørne — området blir en firkant": "Vilkite nuo kampo iki kampo — plotas taps stačiakampiu",
  "Nivået området legges på — samme etasjer som minikartet": "Lygis, kuriame dedamas plotas — tie patys aukštai kaip mini žemėlapyje",
  "Dra i modellen der området skal ligge — slipp for å skrive markeringen": "Vilkite modelyje ten, kur turi būti plotas — atleiskite, kad parašytumėte žymą",
