  "… og {0} til (summene øverst gjelder alle).": "… ir dar {0} (sumos viršuje apima visus).",
  "… og {0} til (summene øverst gjelder alle). Endre grensen i ⚙ Innstillinger → Visning.": "… ir dar {0} (sumos viršuje apima visus). Ribą keiskite ⚙ Nustatymai → Rodymas.",
  "Shift-klikk legger til/fjerner. Shift + dra lager markeringsboks: mot høyre = kun synlige, mot venstre = alt i boksen. Vanlig klikk nullstiller.": "„Shift“ + spustelėjimas prideda/pašalina. „Shift“ + vilkimas kuria žymėjimo langelį: į dešinę = tik matomi, į kairę = viskas langelyje. Paprastas spustelėjimas atstato.",

