  "Grupper (CSV)": "Grupės (CSV)",
  "Alle elementer": "Visi elementai",
  "Kopier": "Kopijuoti",
  "Kopiert": "Nukopijuota",
  "Én rad per gruppe, bare valgt objekttype": "Viena eilutė grupei, tik pasirinktas tipas",
  "Én rad per element – for mengdeberegning og vareordre": "Viena eilutė elementui – kiekiams ir užsakymams",
  "Lim rett inn i et åpent regneark": "Įklijuokite tiesiai į atvirą skaičiuoklę",
  "Klarte ikke å kopiere. Bruk Grupper (CSV) i stedet.": "Nepavyko nukopijuoti. Naudokite Grupės (CSV).",
  "Antall desimaler settes i Innstillinger. Velg objekttype og materiale for å få ett ark om gangen – nedlastingen inneholder bare det som står i lista nå (f.eks. Søyler + Betong gir bare betongsøylene). Materialgruppene samler navn som betyr det samme: «B35», «C35/45» og «Concrete» havner alle under Betong. Mangler materiale på et element, står det ikke i IFC-fila. Lengde = lengste mål per element (ca-verdi, summert per gruppe). Areal = største sammenhengende flate på elementet – vegglivet på en vegg, oversida på et dekke. Det er målet isolasjon, kledning og forskaling bestilles etter, og en døråpning i veggen er trukket fra. Fotavtrykket (grunnflaten sett rett ovenfra) står som egen kolonne sist i regnearket; på et dekke er de to like. Volum er regnet ut av geometrien og gjelder lukkede volumer – hule profiler blir riktige, flater uten tykkelse blir 0.": "Dešimtainiai skaičiai nustatomi Nustatymuose. Pasirinkite objekto tipą ir medžiagą, kad gautumėte po vieną lapą – atsisiuntime yra tik tai, kas dabar sąraše (pvz., Kolonos + Betonas duoda tik betonines kolonas). Medžiagų grupės sujungia tą patį reiškiančius pavadinimus: „B35“, „C35/45“ ir „Concrete“ patenka į Betonas. Jei elementas neturi medžiagos, jos nėra IFC faile. Ilgis = ilgiausias elemento matmuo (apyt., sumuojamas grupėje). Plotas = didžiausias vientisas elemento paviršius – sienos paviršius sienoje, viršus perdangoje. Tai matas, pagal kurį užsakoma izoliacija, apdaila ir klojiniai, o durų anga sienoje atimama. Projekcija iš viršaus (plotas plane) yra atskiras stulpelis lapo gale; perdangoje abu dydžiai sutampa. Tūris skaičiuojamas iš geometrijos ir galioja uždariems tūriams – tuščiaviduriai profiliai teisingi, paviršiai be storio tampa 0.",
