  "Fant ingen fasader med veggelementer å tegne.": "Nerasta fasadų su sienų elementais, kuriuos būtų galima nubraižyti.",
  "SW-Elementer": "SW elementai",
  "Veggene er laget av en eldre versjon — trykk «Generer SW + gulv/ringmur» før du tegner.": "Sienos sukurtos senesnės versijos — prieš braižant paspauskite «Generuoti SW + grindys/pamatas».",
  "Klarte ikke å lage tegninga: ": "Nepavyko sukurti brėžinio: ",
  "Utfyll PDF": "Užpildyti PDF",
  "Dette fyller Storm-tittelfeltet på instruksjonstegninga. Tomt felt hentes fra «Til lista» over; Kontroll og Godkjent står tomme på papiret hvis du ikke fyller dem.": "Tai užpildo Storm brėžinio antraštę instrukciniame brėžinyje. Tuščias laukas imamas iš «Sąrašui» aukščiau; Kontrolė ir Patvirtinta lieka tuščios, jei jų neužpildysite.",
  "Merknad ved fasaden": "Pastaba prie fasado",
  "Veggelementer må kappes og tilpasses til eksisterende fasade. L-Beslag festes til eks. fasade.": "Sienų elementus reikia nupjauti ir pritaikyti prie esamo fasado. L formos kampai tvirtinami prie esamo fasado.",
  "Aksenavnene hentes fra Akser.": "Ašių pavadinimai imami iš Ašys.",
