  "Adressen til byggeplass-tjenesten er ikke satt opp. Den står i js/config.js, og kan overstyres i oppsett.json i SharePoint-mappa.": "Statybvietės paslaugos adresas nenustatytas. Jis yra js/config.js ir gali būti pakeistas oppsett.json faile SharePoint aplanke.",
  "Planner er ikke satt opp ennå. Plan-ID-en legges inn i «oppsett.json» i SharePoint-mappa med modellene.": "„Planner“ dar nesukonfigūruotas. Plano ID įrašomas į „oppsett.json“ SharePoint aplanke su modeliais.",
