  "Fot (ft)": "Pėdos (ft)",
  "Hvilken enhet modellen er TEGNET i. Automatisk gjetter ut fra størrelsen og treffer nesten alltid – men bommer på små modeller i millimeter og på anlegg over en kilometer i meter. Står målene tusen ganger for høyt eller lavt, er det denne du skal endre.": "Kokiais vienetais modelis NUBRAIŽYTAS. Automatinis spėja pagal dydį ir beveik visada pataiko – bet klysta su mažais modeliais milimetrais ir su daugiau nei kilometro objektais metrais. Jei matmenys tūkstantį kartų per dideli ar per maži, keiskite čia.",

