  "EM-utkast laget som markering. Gå gjennom skjemaet i markeringen, lås det og last ned PDF.": "Pakeitimo pranešimo juodraštis sukurtas kaip žymė. Peržiūrėkite formą žymėje, užrakinkite ją ir atsisiųskite PDF.",
  "Endring": "Pokytis",
  "Endringsmelding": "Pakeitimo pranešimas",
  "Endringsmelding fra modellen": "Pakeitimo pranešimas iš modelio",
  "Etter Sammenlign (i Bygg Info) åpner du Endringsmelding: mengdeendringen per elementtype, med pris fra Priskalkulasjon. Kryss av linjene, velg enhet og skriv tittel. Lag EM-utkast tar før- og etter-bilder av hver endring (bare de elementene vises) og fyller ut EM-skjemaet. EM-en lagres internt i SharePoint og følger aldri med ut til byggeplassen. I fanen Endringsmeldinger finner du alle: åpne skjemaet, last ned PDF (bildene står på egne sider bakerst) og flytt den fra Opprettet til Sendt og Fullført (godkjent eller avvist). Mengdene er et anslag fra modellen, ikke oppmål.": "Po Palyginti (Pastato informacija) atidarykite Pakeitimo pranešimą: kiekio pokytis pagal elemento tipą su kainomis iš Kainų skaičiavimo. Pažymėkite eilutes, pasirinkite vienetus ir įrašykite pavadinimą. Sukurti juodraštį nufotografuoja kiekvieną pakeitimą prieš ir po (rodomi tik tie elementai) ir užpildo formą. Pranešimas saugomas viduje SharePoint ir niekada nepatenka į statybvietę. Skirtuke „Pakeitimų pranešimai“ rasite visus: atidarykite formą, atsisiųskite PDF (nuotraukos atskiruose puslapiuose gale) ir perkelkite iš Sukurta į Išsiųsta ir Užbaigta (patvirtinta arba atmesta). Kiekiai yra modelio įvertis, ne matavimas.",
