  "Trykk på en takplate. Dra i den blå pila for lengden eller den oransje for bredden — eller ta tak i enden som før. Shift+klikk for å ta flere.": "Spustelėkite stogo lakštą. Tempkite mėlyną rodyklę ilgiui arba oranžinę pločiui — arba imkite už galo kaip anksčiau. Shift+spustelėjimas – keliems.",
  "Trykk på en takplate. Dra i en av de blå pilene for lengden eller en av de oransje for bredden — hver pil flytter sin egen kant. Shift+klikk for å ta flere.": "Spustelėkite stogo lakštą. Tempkite vieną iš mėlynų rodyklių ilgiui arba vieną iš oranžinių pločiui — kiekviena rodyklė perkelia savo kraštą. Shift+spustelėjimas – pažymėti daugiau.",
  "Takflate {0} · {1} mm": "Stogo plokštuma {0} · {1} mm",
  "Legg til plate": "Pridėti lakštą",
  "Nullstille alle håndjusteringene av takplatene?": "Atstatyti visus rankinius stogo lakštų koregavimus?",
  "Juster TRP": "Koreguoti TRP",
  "Juster tak": "Koreguoti stogą",
  "Fjerne taket? De {0} håndjusteringene forsvinner også.": "Pašalinti stogą? Taip pat dings {0} rankiniai koregavimai.",
  "Platene over bjelka (mm)": "Lakštai virš sijos (mm)",
  "Ingen av takbjelkene ligger med fall. Velg fallretning selv nedenfor.": "Nė viena stogo sija neguli nuolydyje. Pasirinkite nuolydžio kryptį žemiau.",
  "Platene følger bjelkene: {0} takflater av {1} bjelker. Ingen retning er gjettet.": "Lakštai seka sijas: {0} stogo plokštumos iš {1} sijų. Jokia kryptis nespėliojama.",
  "Automatisk — platene følger bjelkene": "Automatiškai — lakštai seka sijas",
  "Fallet leses av {0} takbjelker — de ligger allerede i fallet.": "Nuolydis nuskaitomas iš {0} stogo sijų — jos jau guli nuolydyje.",
  "Stålet er ikke lest inn ennå. Trykk «Generer tak» — den henter det først.": "Plienas dar nenuskaitytas. Paspauskite „Generuoti stogą“ — jis pirmiausia jį paims.",
  "Fant stål, men ingen bjelker øverst å bygge takflata av.": "Rastas plienas, bet nėra viršutinių sijų stogo plokštumai sudaryti.",
  "Klarte ikke å hente stålet: ": "Nepavyko gauti plieno: ",
  "Fant ikke stål å bygge takflata av. Taket bygges av de øverste bjelkene.": "Nerasta plieno stogo plokštumai sudaryti. Stogas formuojamas iš viršutinių sijų.",
  "Taket er flatt. Fallretningen settes nedenfor, og fallprosenten bestemmer hvor mye det heller.": "Stogas plokščias. Nuolydžio kryptis nustatoma žemiau, o nuolydžio procentas lemia pasvirimą.",
  "Fallet leses av gavlfasaden — {0} mm fra raft til møne.": "Nuolydis nuskaitomas iš skydinio fasado — {0} mm nuo karnizo iki kraigo.",
  "Ytterste kant står udekket med {0} mm. Resten er smalere enn én bølge og kan ikke lappes over naboplata — det meste av den er utstikket på flata.": "Išorinis kraštas lieka nepadengtas {0} mm. Likutis siauresnis nei viena banga ir negali būti uždėtas ant gretimo lakšto — didesnė jo dalis yra plokštumos iškiša.",
  "{0} plater blir kortere enn 500 mm. Platelengdene går ikke opp med overlappen — juster stabelen.": "{0} lakštai trumpesni nei 500 mm. Lakštų ilgiai nesutampa su užlaida — pakoreguokite rinkinį.",
  "Platene": "Lakštai",
  "stk": "vnt.",
  "Takoppsett": "Stogo nustatymai",
  "Fallretning": "Nuolydžio kryptis",
