  "Platelengder fra gesimsen og opp (mm) — tom = automatisk": "Lakštų ilgiai nuo karnizo aukštyn (mm) — tuščia = automatiškai",
  "Skriv stabelen fra gesimsen og opp mot mønet, f.eks. «6000, 6000, 3000». Siste lengde gjentas hvis fallet er lengre. Husk at hver skjøt spiser overlappen: to plater à 6000 med 150 mm overlapp dekker 11 850 mm, ikke 12 000.": "Rašykite rinkinį nuo karnizo link kraigo, pvz. „6000, 6000, 3000“. Paskutinis ilgis kartojasi, jei nuolydis ilgesnis. Atminkite, kad kiekviena sandūra suvalgo užlaidą: du 6000 lakštai su 150 mm užlaida dengia 11 850 mm, o ne 12 000.",
