  "Trykk på et blikkstykke og dra i enden. Shift+klikk for å ta flere.": "Spustelėkite skardos dalį ir tempkite jos galą. Shift+spustelėjimas – kelioms.",
  "Trykk «Generer blikk» først.": "Pirmiausia paspauskite „Generuoti skardas“.",
  "Blikket er generert og følger veggene av seg selv.": "Skardos sugeneruotos ir pačios seka sienas.",
  "Blikket er generert og følger veggene. {0} håndjusteringer ligger på.": "Skardos sugeneruotos ir seka sienas. Pritaikyti {0} rankiniai koregavimai.",
  "Generer blikk": "Generuoti skardas",
  "Gi oppsettet et navn og lagre det. Trykk på navnet senere for å legge samme profilmål og håndjusteringer på bygget igjen.": "Pavadinkite rinkinį ir išsaugokite. Vėliau spustelėkite pavadinimą, kad tie patys profilių matmenys ir koregavimai vėl būtų pritaikyti.",
  "Instruksjonstegninga for blikket bygges i en senere runde.": "Skardų instrukcinis brėžinys bus sukurtas vėlesniame etape.",
