  "Terreng": "Reljefas",
  "Terreng: hent landskapet rundt byggeplassen og sett modellen ned i det": "Reljefas: atsisiųskite vietovę aplink statybvietę ir įstatykite į ją modelį",
  "Adresse eller koordinat": "Adresas arba koordinatė",
  "f.eks. Industriveien 20, Geithus": "pvz. Industriveien 20, Geithus",
  "Utsnitt": "Iškarpa",
  "Hent terreng": "Gauti reljefą",
  "Skriv en adresse eller en koordinat først.": "Pirmiausia įveskite adresą arba koordinatę.",
  "Søker etter adressen …": "Ieškoma adreso …",
  "Fant ingen adresse. Prøv med postnummer eller poststed, eller skriv en UTM33-koordinat.": "Adresas nerastas. Bandykite su pašto kodu ar vietove arba įveskite UTM33 koordinatę.",
  "Velg riktig adresse:": "Pasirinkite teisingą adresą:",
  "Fikk ikke kontakt med Kartverket. Sjekk nettet og prøv igjen.": "Nepavyko susisiekti su Kartverket. Patikrinkite ryšį ir bandykite dar kartą.",
  "Henter høydedata fra Kartverket …": "Gaunami aukščio duomenys iš Kartverket …",
  "Kartverket har ingen høydedata her (sjø, eller utenfor dekningen).": "Čia nėra aukščio duomenų (jūra arba už aprėpties ribų).",
  "Klarte ikke å hente terrenget: ": "Nepavyko gauti reljefo: ",
  "moh.": "m virš j. l.",
  "Henter 1 m terrengmodell fra Kartverket. Terrenget viser bakken slik den var da den ble laserskannet — før graving.": "Gaunamas 1 m reljefo modelis iš Kartverket. Jis rodo žemę tokią, kokia buvo lazerinio skenavimo metu — prieš kasimo darbus.",
  "Lastet terreng": "Įkeltas reljefas",
  "Fjern terrenget": "Pašalinti reljefą",
  "Terrenghøyde i adressepunktet:": "Žemės aukštis adreso taške:",
  "Foreløpig plassering: adressepunktet ligger midt under modellen, i høyde med modellens laveste punkt. Flytting, rotasjon og gulvkote kommer i neste trinn.": "Laikina padėtis: adreso taškas yra po modelio viduriu, žemiausio modelio taško aukštyje. Perkėlimas, pasukimas ir grindų aukštis bus kitame žingsnyje.",
  "Kontroller målestokken: mål en kjent avstand på terrenget med Mål.": "Patikrinkite mastelį: išmatuokite žinomą atstumą reljefe įrankiu Matavimas.",
  "Utsnittet er": "Iškarpa yra",
  "Plasseringen er omtrentlig (±1–2 m) og skal aldri brukes til utstikking.": "Padėtis apytikslė (±1–2 m) ir niekada negali būti naudojama nužymėjimui.",
  "svarte ikke innen {0} sekunder": "neatsakė per {0} sekundžių",
  "nettleseren fikk ikke svar (nett, brannmur eller tjenesten nede)": "naršyklė negavo atsakymo (tinklas, užkarda arba paslauga neveikia)",
  "Hentet": "Gauta",
  "Beskjær": "Apkarpyti",
  "Dra i de røde håndtakene i 3D-vinduet for å beskjære terrenget. Hele utsnittet er tatt vare på — dra ut igjen, så kommer det tilbake uten å hente på nytt.": "Tempkite raudonas rankenėles 3D lange, kad apkarpytumėte reljefą. Visa iškarpa išsaugoma — ištempkite atgal ir ji sugrįš be pakartotinio atsisiuntimo.",
  "Vis hele utsnittet": "Rodyti visą iškarpą",
