  "Flytt og roter bygget": "Perkelti ir pasukti pastatą",
  "Dra i det hvite fotavtrykket for å flytte bygget. Dra i det hvite håndtaket foran bygget for å rotere — det snapper til hver 90°. Esc avslutter.": "Tempkite baltą kontūrą, kad perkeltumėte pastatą. Tempkite baltą rankenėlę priešais pastatą, kad pasuktumėte — pritraukiama kas 90°. Esc baigia.",
