  "Byggets senter står": "Pastato centras yra",
  "fra adressepunktet.": "nuo adreso taško.",
  "Gulvkote": "Grindų aukštis",
  "Gulvkote (moh.)": "Grindų aukštis (m virš j. l.)",
  "f.eks. 75,30": "pvz. 75,30",
  "Grovt: beregnet fra laveste terrengpunkt under bygget, ikke oppgitt. Skriv gulvkoten fra tegningen.": "Apytiksliai: apskaičiuota pagal žemiausią žemės tašką po pastatu, nenurodyta. Įveskite grindų aukštį iš brėžinio.",
  "Oppgitt fra tegningen.": "Nurodyta iš brėžinio.",
  "Modellens ±0 regnes som gulv. ▲ Kote viser nå moh.": "Modelio ±0 laikomas grindimis. ▲ Aukštis dabar rodo m virš j. l.",
  "Modellen har ikke ±0 innenfor seg — modellens laveste punkt regnes som gulv. ▲ Kote viser nå moh.": "Modelyje nėra ±0 — žemiausias jo taškas laikomas grindimis. ▲ Aukštis dabar rodo m virš j. l.",
  "Legg oppå terrenget": "Padėti ant žemės",
  "Utskjæring rundt bygget": "Iškirtimas aplink pastatą",
  "Skjær ut terrenget og legg en flat plate i gulvhøyde": "Iškirpti reljefą ir paklota plokščią aikštelę grindų lygyje",
  "Dra i de gule håndtakene for å endre størrelsen på plata.": "Tempkite geltonas rankenėles, kad pakeistumėte aikštelės dydį.",
  "Tilbakestill (2 m rundt bygget)": "Atstatyti (2 m aplink pastatą)",
  "Gulvet er modellens laveste punkt — bunnen av søylene, toppen av betonggulvet. ▲ Kote viser nå moh.": "Grindys yra žemiausias modelio taškas — kolonų apačia, betoninių grindų viršus. ▲ Aukštis dabar rodo m virš j. l.",
