  "Slette {0}?": "Ištrinti {0}?",
  "Del støpene i etapper. Gi hver etappe en dato, og merk den som støpt når den er ferdig. Velg elementer i modellen (shift-klikk eller shift-dra) og trykk «Legg til valgte» på etappen.": "Padalykite betonavimą į etapus. Kiekvienam etapui nurodykite datą ir pažymėkite kaip išbetonuotą, kai baigtas. Pasirinkite elementus modelyje (shift+spustelėjimas arba shift+tempimas) ir etape paspauskite „Pridėti pasirinktus“.",
  "{0} elementer lagt i {1}. {2} av dem er flyttet fra en annen etappe.": "{0} elementų pridėta į {1}. {2} iš jų perkelti iš kito etapo.",
  "{0} elementer lagt i {1}.": "{0} elementų pridėta į {1}.",
  "ca {0}": "apie {0}",
  "+ Legg til valgte ({0})": "+ Pridėti pasirinktus ({0})",
  "+ Legg til valgte": "+ Pridėti pasirinktus",
  "Vis etappen i modellen": "Rodyti etapą modelyje",
  "Skjul etappen i modellen": "Slėpti etapą modelyje",
  "Ta alle elementene ut av etappen?": "Pašalinti visus elementus iš etapo?",
  "Betonggulv": "Betoninės grindys",
  "Isolasjon under": "Izoliacija apačioje",
  "Del støpene i etapper. Gi hver etappe en dato, og merk den som støpt når den er ferdig. Velg elementer i modellen (shift-klikk eller shift-dra) og trykk «Legg til valgte» på etappen. Generert betonggulv og ringmur kan også legges inn.": "Padalykite betonavimą į etapus. Kiekvienam etapui nurodykite datą ir pažymėkite kaip išbetonuotą, kai baigtas. Pasirinkite elementus modelyje (shift+spustelėjimas arba shift+tempimas) ir etape paspauskite „Pridėti pasirinktus“. Taip pat galima pridėti sugeneruotas betonines grindis ir cokolį.",
  "Legg til i {0}": "Pridėti į {0}",
  "Trykk på elementene som skal med. Shift + dra for mange på en gang.": "Spustelėkite elementus, kuriuos norite įtraukti. Shift + tempkite, kad pažymėtumėte daug iš karto.",
  "Del støpene i etapper. Gi hver etappe en dato, og merk den som støpt når den er ferdig. Trykk «Legg til» på etappen og velg elementene i modellen — også generert betonggulv og ringmur. Trykk «Ferdig» når du er ferdig.": "Padalykite betonavimą į etapus. Kiekvienam etapui nurodykite datą ir pažymėkite kaip išbetonuotą, kai baigta. Paspauskite „Pridėti“ prie etapo ir pasirinkite elementus modelyje — taip pat sugeneruotas grindis ir cokolį. Baigę paspauskite „Baigta“.",
  "Velger …": "Renkama …",
  "+ Legg til": "+ Pridėti",
  "Trykk på plata der det første hjørnet skal være.": "Spustelėkite plokštę ten, kur turi būti pirmasis kampas.",
  "Trykk der det motsatte hjørnet skal være.": "Spustelėkite ten, kur turi būti priešingas kampas.",
  "Trykk i hvert hjørne. Dobbeltklikk, Enter eller trykk på første hjørne for å avslutte.": "Spustelėkite kiekvieną kampą. Norėdami baigti, spustelėkite dukart, paspauskite Enter arba spustelėkite pirmąjį kampą.",
  "Nytt felt i {0}": "Naujas laukas – {0}",
  "Rektangel": "Stačiakampis",
  "Polygon": "Daugiakampis",
  "Del støpene i etapper. Gi hver etappe en dato, og merk den som støpt når den er ferdig. Trykk «Legg til» på etappen og velg elementene i modellen — også generert betonggulv og ringmur. Trykk «Ferdig» når du er ferdig. «+ Felt» tegner et felt på plata.": "Padalykite betonavimą į etapus. Kiekvienam etapui nurodykite datą ir pažymėkite kaip išbetonuotą, kai baigta. Paspauskite „Pridėti“ prie etapo ir pasirinkite elementus modelyje — taip pat sugeneruotas grindis ir cokolį. Baigę paspauskite „Baigta“. „+ Laukas“ nubraižo lauką ant plokštės.",
  "Vis og juster feltet": "Rodyti ir koreguoti lauką",
  "Felt {0}": "Laukas {0}",
  "Slett feltet": "Ištrinti lauką",
  "Kanter (m):": "Kraštinės (m):",
  "Dra de hvite prikkene (hjørner) eller de gule (kanter). Dra inne i feltet for å flytte det. Dobbeltklikk på en kant gir et nytt hjørne. Delete sletter. Ctrl+Z angrer.": "Tempkite baltus taškus (kampus) arba geltonus (kraštines). Tempkite lauko viduje, kad jį perkeltumėte. Dukart spustelėkite kraštinę – naujas kampas. Delete ištrina. Ctrl+Z atšaukia.",
  "Tegner …": "Braižoma …",
  "+ Felt": "+ Laukas",
  "Vist per": "Rodoma",
  "— slik det var": "— kaip buvo",
  "— slik det skal bli": "— pagal planą",
  "I dag": "Šiandien",
  "Vis etappeplan": "Rodyti etapų planą",
  "farger betongen etter støpeplanen": "nuspalvina betoną pagal betonavimo planą",
  "Støpt {0}": "Išbetonuota {0}",
  "Angre «støpt»": "Atšaukti „išbetonuota“",
  "Merk som støpt": "Pažymėti kaip išbetonuotą",
  "Ingen dato": "Nėra datos",
  "Etappe {0}": "Etapas {0}",
  "Areal (ca)": "Plotas (apie)",
  "Støpeplanen": "Betonavimo planas",
  "Har prosjektlederen laget en støpeplan, står knappen Støpeplan i Planlegging. Betongen er farget etter etappen den støpes i: full farge er støpt, svakere farge kommer senere. Tidslinjen nederst viser datoene — dra i den for å se hvordan det skal se ut en annen dag, og trykk I dag for å komme tilbake. Trykk på et felt på plata for etappe, dato og mengde.": "Jei projekto vadovas sudarė betonavimo planą, mygtukas Betonavimo planas yra skiltyje Planavimas. Betonas nuspalvintas pagal etapą, kuriame jis betonuojamas: ryški spalva – išbetonuota, blyškesnė – bus vėliau. Laiko juosta apačioje rodo datas — tempkite ją, kad pamatytumėte, kaip turi atrodyti kitą dieną, ir paspauskite Šiandien, kad grįžtumėte. Spustelėkite lauką ant plokštės – matysite etapą, datą ir kiekį.",
  "Støpeplan: etapper, felt og tidslinje": "Betonavimo planas: etapai, laukai ir laiko juosta",
  "Støpeplan (i Planlegging) deler støpene i etapper. Trykk + Legg til på etappen og velg elementene i modellen, eller + Felt for å tegne et felt på plata — dra hjørner og kanter for å justere. Merk som støpt når etappen er ferdig. Tidslinjen nederst viser planen på en valgt dag, og Vis etappeplan skrur fargingen av og på. Planen følger med ut til byggeplassen når du trykker Storm-Byggeplass.": "Betonavimo planas (skiltyje Planavimas) padalija betonavimą į etapus. Paspauskite + Pridėti prie etapo ir pasirinkite elementus modelyje arba + Laukas, kad nubraižytumėte lauką ant plokštės — tempkite kampus ir kraštines, kad pakoreguotumėte. Pažymėkite kaip išbetonuotą, kai etapas baigtas. Laiko juosta apačioje rodo planą pasirinktą dieną, o Rodyti etapų planą įjungia ir išjungia spalvinimą. Planas perduodamas į statybvietę, kai paspaudžiate Storm-Byggeplass.",
  "({0} plater à {1} m, {2} skjøter à 5 cm)": "({0} plokštės po {1} m, {2} užleidimai po 5 cm)",
  "{0} plater à {1} m, {2} skjøter à 5 cm": "{0} plokštės po {1} m, {2} užleidimai po 5 cm",
