  "Volum fra modellen (elementer) og felt × tykkelse, uten svinn eller ekstra betong. Cemflex VB 150, plater à {0} m, minst 5 cm omlegg per skjøt. Injeksjonsslange uten skjøt.": "Tūris iš modelio (elementai) ir laukai × storis, be nuostolių ir papildomo betono. Cemflex VB 150, plokštės po {0} m, ne mažiau kaip 5 cm užleidimas sandūroje. Injekcinė žarna be sandūrų.",
