  "Stålbunker fra stålmodellen": "Plieno rietuvės iš plieno modelio",
  "Søylene og bjelkene i modellen legges i bunker rundt bygget, én bunke per profil og lengde. Søyler og bjelker ligger alltid i hver sin bunke.": "Modelio kolonos ir sijos sudedamos į rietuves aplink pastatą, po vieną rietuvę kiekvienam profiliui ir ilgiui. Kolonos ir sijos visada atskirose rietuvėse.",
