  "Fagverk halvdel": "Santvaros pusė",
  "Fagverk kjennes igjen av seg selv (to korder med stag imellom) og legges som halvdeler, delt midt på, flatt på strøer.": "Santvaros atpažįstamos automatiškai (dvi juostos su statramsčiais tarp jų) ir dedamos kaip pusės, padalytos per vidurį, gulsčios ant tarpinių.",
  "Trykk på det som skal med — elementer, SW, takplater, blikk, rigg, materiell og markeringer. Det som allerede ligger i et trinn, er skjult. Shift + dra for mange på en gang.": "Spustelėkite tai, kas turi būti įtraukta — elementus, SW, stogo lakštus, skardinimus, statybvietės įrangą, medžiagas ir žymes. Tai, kas jau yra žingsnyje, paslėpta. Shift + vilkite, kad pažymėtumėte daug iš karto.",
  "Ingenting lagt til ennå": "Dar nieko nepridėta",
  "Del arbeidet i trinn med dato. Trykk «Legg til» på trinnet og velg det som utføres da — elementer, SW-elementer, takplater, blikk, rigg, materiell og markeringer. Trykk «Ferdig» når du er ferdig. Kom noe med ved en feil, tar «− Fjern» det ut igjen.": "Padalykite darbą į žingsnius su datomis. Paspauskite „Pridėti“ prie žingsnio ir pasirinkite, kas tada atliekama — elementus, SW elementus, stogo lakštus, skardinimus, statybvietės įrangą, medžiagas ir žymes. Baigę paspauskite „Baigta“. Jei kas nors pridėta per klaidą, „− Pašalinti“ tai pašalins.",
