  "Trykk på det som skal ut av trinnet. Bare det som ligger i trinnet kan velges; det som ligger i andre trinn er skjult. Shift + dra for mange på en gang.": "Spustelėkite tai, kas turi būti pašalinta iš žingsnio. Galima pasirinkti tik tai, kas yra šiame žingsnyje; kas yra kituose žingsniuose, paslėpta. Shift + vilkite, kad pažymėtumėte daug iš karto.",
