  "Farget: nytt i trinn {0} · Vanlige farger: utført i tidligere trinn": "Spalvota: nauja žingsnyje {0} · Įprastos spalvos: atlikta ankstesniuose žingsniuose",
  "Én side per trinn: bygget sett fra nord, sør, øst og vest, og det som er nytt i trinnet": "Vienas puslapis žingsniui: pastatas iš šiaurės, pietų, rytų ir vakarų bei tai, kas nauja žingsnyje",
  "Se videoen av hele framdriften": "Žiūrėkite viso grafiko vaizdo įrašą",
  "Skann med mobilen (SharePoint, Storm-innlogging)": "Nuskenuokite telefonu (SharePoint, Storm prisijungimas)",
  "Lager video …": "Kuriamas vaizdo įrašas …",
  "Lager video … {0} %": "Kuriamas vaizdo įrašas … {0} %",
  "Nettleseren kan ikke lage video.": "Naršyklė negali sukurti vaizdo įrašo.",
  "Lagrer videoen i SharePoint …": "Vaizdo įrašas išsaugomas SharePoint …",
  "Klarte ikke å lage videoen: {0}": "Nepavyko sukurti vaizdo įrašo: {0}",
  "Kameraet går én gang rundt bygget mens trinnene bygges opp. Lagres i SharePoint, så PDF-en får en QR-kode til videoen.": "Kamera vieną kartą apsuka pastatą, kol statomi žingsniai. Išsaugoma SharePoint, kad PDF gautų QR kodą į vaizdo įrašą.",
  "Lag video": "Kurti vaizdo įrašą",
  "Videoen er lastet ned og lagret i SharePoint. PDF-en får nå en QR-kode til den.": "Vaizdo įrašas atsisiųstas ir išsaugotas SharePoint. PDF dabar gaus QR kodą į jį.",
  "Videoen er lastet ned. Logg inn (den røde prikken øverst til høyre) og lag den på nytt for å lagre den i SharePoint — da får PDF-en en QR-kode til den.": "Vaizdo įrašas atsisiųstas. Prisijunkite (raudonas taškas viršuje dešinėje) ir sukurkite jį iš naujo, kad išsaugotumėte SharePoint — tada PDF gaus QR kodą.",
  "Framdriftsplanen": "Darbų grafikas",
  "Framdriftsplan: trinn, glider, PDF og video": "Darbų grafikas: etapai, slankiklis, PDF ir vaizdo įrašas",
  "Har prosjektlederen laget en framdriftsplan, står knappen Framdriftsplan i Planlegging. Panelet viser trinnene med datoer og hva som utføres i hvert. Dra glideren nederst for å se hva som er bygget en bestemt dag: det som kommer senere er skjult, det som er i arbeid tones inn, og materiellbunkene blir mindre etter hvert som det de er levert til monteres — antallet på navnelappen teller ned. Trykk på et trinn for å gå dit det er ferdig, Spill av for å se hele planen, og I dag for å komme tilbake.": "Jei projekto vadovas parengė darbų grafiką, skiltyje Planavimas yra mygtukas Darbų grafikas. Skydelyje rodomi etapai su datomis ir kas atliekama kiekviename. Vilkite slankiklį apačioje, kad pamatytumėte, kas pastatyta tam tikrą dieną: kas bus vėliau, paslėpta, kas vykdoma, ryškėja, o medžiagų krūvos mažėja, kai sumontuojama tai, kam jos atvežtos — skaičius etiketėje mažėja. Bakstelėkite etapą, kad nueitumėte iki jo pabaigos, Leisti — kad pamatytumėte visą planą, ir Šiandien — kad grįžtumėte.",
  "Framdriftsplan (i Planlegging) deler arbeidet i trinn med Fra- og Til-dato. Trykk + Legg til på trinnet og velg det som utføres da — elementer, SW-elementer, takplater, blikk, rigg, materiell og markeringer (trykk, eller shift + dra en boks). Det som allerede ligger i et trinn, er skjult mens du velger. − Fjern tar ting ut igjen. Glideren nederst viser bygget en valgt dag, og materiellbunkene brukes opp etter hvert som det de er levert til monteres. Last ned PDF gir én side per trinn, Lag video en film der kameraet går rundt bygget — videoen lagres i SharePoint, og PDF-en får en QR-kode til den. Planen følger med ut til byggeplassen når du trykker Storm-Byggeplass.": "Darbų grafikas (Planavimas) padalija darbus į etapus su data Nuo ir Iki. Paspauskite + Pridėti prie etapo ir pasirinkite, kas tada atliekama — elementai, SW elementai, stogo lakštai, skardinimas, statybvietės įranga, medžiagos ir žymos (spustelėkite arba shift + vilkite rėmelį). Tai, kas jau yra kuriame nors etape, pasirenkant paslėpta. − Pašalinti išima dalykus atgal. Slankiklis apačioje rodo pastatą pasirinktą dieną, o medžiagų krūvos sunaudojamos montuojant. Atsisiųsti PDF pateikia po vieną puslapį etapui, Kurti vaizdo įrašą — filmą, kuriame kamera apskrieja pastatą; vaizdo įrašas išsaugomas SharePoint, o PDF gauna QR kodą į jį. Planas iškeliauja į statybvietę paspaudus Storm-Byggeplass.",
  "Planen er laget på kontoret. Dra glideren nederst for å se hva som er bygget når — trykk på et trinn for å gå dit det er ferdig.": "Planas parengtas biure. Vilkite slankiklį apačioje, kad pamatytumėte, kas pastatyta kada — bakstelėkite etapą, kad nueitumėte iki jo pabaigos.",
  "Slik bruker du framdriftsplanen": "Kaip naudotis darbų grafiku",
