  "Tak {0}": "Stogas {0}",
  "Tak-generatoren har ikke lagt tak — regnet som flatt tak over modellen. Velg takform og vinkel over.": "Stogo generatorius nesukūrė stogo — skaičiuota kaip plokščias stogas virš modelio. Pasirinkite stogo formą ir kampą aukščiau.",
  "Ingen tak fra tak-generatoren — taket er lest av stålet (uten søyler og søyleforlengere): {0}, {1}°. Skriv inn en takvinkel for å overstyre vinkelen.": "Stogo generatorius stogo nesukūrė — stogas nuskaitytas iš plieno (be kolonų ir kolonų pailginimų): {0}, {1}°. Įveskite stogo nuolydį, kad jį pakeistumėte.",
  "Takvinkelen du skrev inn ({0}°) er brukt på taket lest av stålet ({1}).": "Įvestas stogo nuolydis ({0}°) pritaikytas stogui, nuskaitytam iš plieno ({1}).",
  "sk,0 ({0} kN/m²) er større enn sk,maks ({1} kN/m²). Da blir sk,maks brukt — sjekk begge tallene mot standarden eller RIB.": "sk,0 ({0} kN/m²) didesnis nei sk,max ({1} kN/m²). Tada naudojamas sk,max — patikrinkite abi reikšmes pagal standartą arba su konstruktoriumi.",
  "Hg er lik høyden over havet ({0} moh). Hg er kommunens grensehøyde fra standarden, ikke byggets høyde — sjekk tallet.": "Hg lygus aukščiui virš jūros lygio ({0} m). Hg yra savivaldybės ribinis aukštis iš standarto, o ne pastato aukštis — patikrinkite reikšmę.",
  "Taket": "Stogas",
  "Takflate {0}": "Stogo plokštuma {0}",
  "Takhalvdel {0}": "Stogo pusė {0}",
  "Takvinkel": "Stogo kampas",
  "Terrengkategori": "Vietovės kategorija",
  "Veiledende kontroll og visualisering. Erstatter ikke RIB, som har ansvaret for prosjekteringen (PRO). Kommuneverdiene skrives inn fra NS-EN 1991-1-3 og NS-EN 1991-1-4 med nasjonalt tillegg, eller fra RIBs lastforutsetninger.": "Orientacinė patikra ir vizualizacija. Nepakeičia konstruktoriaus (RIB), atsakingo už projektavimą. Savivaldybės reikšmės įvedamos iš NS-EN 1991-1-3 ir NS-EN 1991-1-4 su nacionaliniu priedu arba iš konstruktoriaus apkrovų prielaidų.",
  "Vind på skrått tak (over 5°) er ikke med i denne versjonen — se tabell 7.3–7.4 i standarden.": "Vėjas ant šlaitinio stogo (virš 5°) šioje versijoje neįtrauktas — žr. standarto 7.3–7.4 lenteles.",
  "Vind · qp {0} kN/m²": "Vėjas · qp {0} kN/m²",
  "Sonene ligger utenpå veggelementene og ringmuren ({0} fasader), fra ende til ende og bunn til topp.": "Zonos yra sienų elementų ir cokolio išorėje ({0} fasadai), nuo galo iki galo ir nuo apačios iki viršaus.",
  "Ingen SW-vegger: sonene ligger utenpå stålsøylene i hver fasade, fra ende til ende og bunn til topp.": "Nėra SW sienų: zonos yra plieno kolonų išorėje kiekviename fasade, nuo galo iki galo ir nuo apačios iki viršaus.",
  "Per fasade": "Pagal fasadą",
  "Sum veggareal": "Bendras sienų plotas",
  "Side {0}": "Pusė {0}",
  "Vindkasthastighetstrykk qp(h)": "Didžiausias vėjo greičio slėgis qp(h)",
  "Vindlast (NS-EN 1991-1-4)": "Vėjo apkrova (NS-EN 1991-1-4)",
  "Vindretning": "Vėjo kryptis",
  "Vis snølast": "Rodyti sniego apkrovą",
  "Vis vindlast": "Rodyti vėjo apkrovą",
  "f.eks. Modum": "pvz. Modum",
  "fra terrenget: {0}": "iš reljefo: {0}",
  "kN/m² per 100 m": "kN/m² 100 m",
  "Tak (takplater)": "Stogas (stogo plokštės)",
  "Snø & Last": "Sniegas ir apkrova",
  "Snø & Last: veiledende snølast på taket og vindlast på fasadene": "Sniegas ir apkrova: orientacinė sniego apkrova stogui ir vėjo apkrova fasadams",
  "Snø & Last: veiledende laster": "Sniegas ir apkrova: orientacinės apkrovos",
  "Snø & Last (i Bygg Info) regner snølasten på hver takflate og vindtrykket på fasadene og et flatt tak. Skriv inn kommuneverdiene fra standarden eller RIBs lastforutsetninger (sk,0, Hg, Δsk, vb,0), velg terrengkategori og vindretning, og trykk Vis snølast eller Vis vindlast for å se lastene i farger i modellen. Taket Automatisk bruker tak-generatorens regler (de øverste bjelkene), og fasadene er kantene av byggets omriss — likt med og uten veggelementer. Høyden over havet kan hentes fra terrenget. Dette er en veiledende kontroll — den erstatter ikke RIB.": "Sniegas ir apkrova (Pastato info) skaičiuoja sniego apkrovą kiekvienai stogo plokštumai ir vėjo slėgį fasadams bei plokščiam stogui. Įveskite savivaldybės reikšmes iš standarto arba konstruktoriaus prielaidų (sk,0, Hg, Δsk, vb,0), pasirinkite vietovės kategoriją ir vėjo kryptį, tada spauskite Rodyti sniego apkrovą arba Rodyti vėjo apkrovą, kad modelyje matytumėte apkrovas spalvomis. Stogas Automatiškai naudoja stogo generatoriaus taisykles (viršutinės sijos), o fasadai yra pastato kontūro kraštinės — vienodai su sienų elementais ir be jų. Aukštį virš jūros lygio galima paimti iš reljefo. Tai orientacinė patikra — ji nepakeičia konstruktoriaus.",
  "0 – åpent hav": "0 – atvira jūra",
  "I – kystnært, åpent": "I – pakrantė, atvira",
  "II – landbruk, spredte hus": "II – žemės ūkis, pavieniai namai",
  "III – tettsted, skog": "III – gyvenvietė, miškas",
  "IV – by, minst 15 % bebygd": "IV – miestas, bent 15 % užstatyta",
  "Hentet fra terrenget (adressen)": "Paimta iš reljefo (adresas)",
  "Hentet fra terrenget": "Paimta iš reljefo",
  "vb,0 er {0} m/s. Referansevindhastigheten i Norge er vanligvis mellom 22 og 31 m/s — sjekk tallet.": "vb,0 yra {0} m/s. Bazinis vėjo greitis Norvegijoje paprastai yra 22–31 m/s — patikrinkite reikšmę.",
  "{1} er {0}. Den skal ligge mellom 0 og 1,0 (normalt 1,0).": "{1} yra {0}. Turi būti tarp 0 ir 1,0 (paprastai 1,0).",
  "{1} er {0}. Høydefaktoren er 1,0 eller litt større — aldri under 1,0.": "{1} yra {0}. Aukščio koeficientas yra 1,0 arba šiek tiek didesnis — niekada mažesnis nei 1,0.",
  "{1} er {0}. Sannsynlighetsfaktoren er normalt 1,0 (50 års returperiode).": "{1} yra {0}. Tikimybės koeficientas paprastai yra 1,0 (50 metų pasikartojimo periodas).",
  "sk,0 er {0} kN/m². Det er utenfor det som er vanlig i Norge — sjekk tallet.": "sk,0 yra {0} kN/m². Tai neįprasta Norvegijai — patikrinkite reikšmę.",
  "{1} er {0}. Den skal normalt være 1,0.": "{1} yra {0}. Paprastai turi būti 1,0.",
  "Skriv bare slutten — «SW-» settes alltid foran. «XX» gir SW-XX, «18*» gir SW-18*. Bare «*» gir forelderens nummer med stjerne.": "Rašykite tik galūnę — «SW-» visada pridedama priekyje. «XX» duoda SW-XX, «18*» duoda SW-18*. Vien «*» duoda tėvinio elemento numerį su žvaigždute.",
  "Tak: TRP-plater lagt på de øverste bjelkene — virker med og uten veggelementer": "Stogas: TRP lakštai ant viršutinių sijų — veikia su sienų elementais ir be jų",
  "Denne fallretningen leses av SW-generatorens fasader. Generer veggelementene, eller velg «Automatisk».": "Ši nuolydžio kryptis nuskaitoma iš SW generatoriaus fasadų. Sugeneruokite sienų elementus arba pasirinkite «Automatiškai».",
  "Ingen takplater er lagt — takflatene er regnet med tak-generatorens regler: de øverste bjelkene, med omrisset av bjelkenes utvendige flate ({0} takflater).": "Stogo lakštai nesudėti — stogo plokštumos apskaičiuotos pagal stogo generatoriaus taisykles: viršutinės sijos, kontūras pagal išorinius sijų paviršius ({0} plokštumos).",
  "Snøen ligger på taket innenfor blikket: omrisset av toppbjelkenes utvendige flate ({0} takflater), løftet opp på takplatene.": "Sniegas guli ant stogo skardinimo viduje: viršutinių sijų išorinio paviršiaus kontūras ({0} stogo plokštumos), pakeltas ant stogo lakštų.",
  "Vis eller skjul hjelpeteksten": "Rodyti arba slėpti pagalbos tekstą",
