  "Over 0,3 m fra veggen ({0}) — innvendig rekkverk er på.": "Daugiau nei 0,3 m nuo sienos ({0}) — vidinis turėklas įjungtas.",
  "Over 0,3 m fra veggen ({0}) uten innvendig rekkverk. Flytt stillaset nærmere eller slå på innvendig rekkverk.": "Daugiau nei 0,3 m nuo sienos ({0}) be vidinio turėklo. Pastumkite pastolius arčiau arba įjunkite vidinį turėklą.",
