  "Trykk på feltet der trappetårnet skal stå — trykk igjen for å fjerne det. Esc når du er ferdig.": "Spustelėkite tarpatramį, kur turi stovėti laiptų bokštas — spustelėkite dar kartą, kad pašalintumėte. Esc, kai baigsite.",
  "Trykk på plata som skal få luke og stige — trykk igjen for å gjøre den tilbake. Esc når du er ferdig.": "Spustelėkite paklotą, kuris turi gauti liuką ir kopėčias — spustelėkite dar kartą, kad atšauktumėte. Esc, kai baigsite.",
