  "Bunnskruene må skrus ut {0} m — mer enn {1} m. Sjekk med leverandøren.": "Sraigtines atramas reikia išsukti {0} m — daugiau nei {1} m. Pasitarkite su tiekėju.",
  "Ekstra rammehøyde nederst i {0} ramme-linjer der fallet er større enn skruene klarer.": "Papildomas rėmo aukštis apačioje {0} rėmų linijose, kur nuolydis didesnis, nei gali išlyginti sraigtinės atramos.",
  "Bunnskruene skrus ut opptil {0} m for å ta opp fallet i terrenget.": "Sraigtinės atramos išsukamos iki {0} m, kad išlygintų reljefo nuolydį.",
