  "Repos": "Aikštelė",
  "Håndlist": "Ranktūris",
  "Fant ingen takbjelker — taket er lest av stålet (uten søyler og søyleforlengere): {0}, {1}°. Velg takform for å skrive inn vinkelen selv.": "Stogo sijų nerasta — stogas nuskaitytas iš plieno (be kolonų ir jų pailginimų): {0}, {1}°. Pasirinkite stogo formą, kad patys įvestumėte kampą.",
  "Fasadene er kantene av byggets omriss sett ovenfra ({0} fasader) — likt med og uten veggelementer. Sonene dekker hver fasade fra ende til ende og bunn til topp.": "Fasadai yra pastato kontūro, matomo iš viršaus, kraštinės ({0} fasadai) — vienodai su sienų elementais ir be jų. Zonos dengia kiekvieną fasadą nuo galo iki galo ir nuo apačios iki viršaus.",
  "Tak: TRP-plater på de øverste bjelkene": "Stogas: TRP lakštai ant viršutinių sijų",
  "Tak (i Storm-Byggeplass) er et eget verktøy og virker med og uten veggelementer. Med fallretning Automatisk legger platene seg langs de øverste bjelkene, så saltak, pulttak og valmtak blir riktige av seg selv. Trykk Generer tak, juster platene om du må, og last ned lista (Excel). Taket blir stående når veggene genereres på nytt.": "Stogas (Storm statybvietėje) yra atskiras įrankis ir veikia su sienų elementais ir be jų. Pasirinkus nuolydžio kryptį Automatiškai, lakštai klojami pagal viršutines sijas, todėl dvišlaičiai, vienšlaičiai ir keturšlaičiai stogai gaunami teisingi patys. Spauskite Generuoti stogą, jei reikia pakoreguokite lakštus ir atsisiųskite sąrašą (Excel). Stogas lieka, kai sienos generuojamos iš naujo.",
  "Blikk ligger i SW-generatoren": "Skardinimas yra SW generatoriuje",
  "Når veggelementene er generert, dukker seksjonen Blikk opp nederst i SW-generatoren. Der genereres toppbeslag, bunnbeslag, hjørnebeslag og hatprofil rundt elementene, med egne profilmål for fasader og innervegger. Blikket regnes av veggene og følger med når de endres.": "Sugeneravus sienų elementus, SW generatoriaus apačioje atsiranda skyrius Skardinimas. Ten generuojami viršutiniai, apatiniai, kampiniai apskardinimai ir skrybėlinis profilis aplink elementus, su atskirais profilių matmenimis fasadams ir vidinėms sienoms. Skardinimas skaičiuojamas pagal sienas ir keičiasi kartu su jomis.",
  // 🌦 Vis vær og 🗂 Prosjektinfo (09.10.2026)
  "Byggherre": "Užsakovas",
  "Kontakt": "Kontaktas",
  "Prosjektets logo": "Projekto logotipas",
  "Vis været på tidslinja (varsel ved storm, mye regn, sterk vind og frost)": "Rodyti orus laiko juostoje (įspėjimai apie audrą, smarkų lietų, stiprų vėją ir šalną)",
  "Fant ingen adresse. Prøv med postnummer eller poststed.": "Adresas nerastas. Bandykite su pašto kodu ar vietove.",
  "ikke fylt ut": "neužpildyta",
  "Åpne en modell først — prosjektinfo lagres per modell.": "Pirmiausia atidarykite modelį — projekto informacija saugoma kiekvienam modeliui.",
  "Fylles inn automatisk i Rapport, Sjekkliste, Støpeplan, Riggplan, Framdriftsplan, SW-tegning, rigg-objektene og Vis vær. Det du skriver i et verktøy, gjelder bare der.": "Automatiškai įrašoma Ataskaitoje, Kontroliniame sąraše, Betonavimo plane, Statybvietės plane, Darbų grafike, SW brėžinyje, statybvietės objektuose ir Rodyti orus. Tai, ką įrašote įrankyje, galioja tik ten.",
