  // 🌦 Vær: meldinger på byggeplassen (09.10.2026)
  "Fikk ikke hentet været — værtjenesten svarer ikke": "Nepavyko gauti orų — orų paslauga neatsako",
  "Været er ikke sendt ut fra kontoret ennå. På kontoret: slå på Vis vær og trykk Storm-Byggeplass.": "Orai iš biuro dar neišsiųsti. Biure: įjunkite Rodyti orus ir paspauskite Storm statybvietė.",
  "Vis vær er av på kontoret. Slå det på og trykk Storm-Byggeplass, så kommer været her.": "Rodyti orus biure išjungta. Įjunkite ir paspauskite Storm statybvietė, tada orai atsiras čia.",
  "Byggeplassens adresse mangler i Innstillinger → Prosjektinfo på kontoret.": "Biure trūksta statybvietės adreso: Nustatymai → Projekto informacija.",
  "Fikk ikke hentet været — værtjenesten svarer ikke. Prøv igjen senere.": "Nepavyko gauti orų — orų paslauga neatsako. Bandykite vėliau.",
  // 🌦 Vær i 3D av/på (09.10.2026)
  "Vis været i Framdriftsplan og 3D (også på byggeplassen)": "Rodyti orus Darbų grafike ir 3D (taip pat statybvietėje)",
  "Vis været i 3D (himmel, skyer, regn og snø)": "Rodyti orus 3D (dangus, debesys, lietus ir sniegas)",
  "Skjul været i 3D": "Slėpti orus 3D",
  "Skru av været i 3D (himmel, regn og snø). Slås på igjen i Vis vær.": "Išjungti orus 3D (dangus, lietus ir sniegas). Vėl įjungiama Rodyti orus.",
  // 💰 Priskalkulasjon og mengdesett fra fila (12.10.2026)
  "Planlegging": "Planavimas",
  "Planlegging av byggeplassen: terreng, rigg, støpeplan, framdriftsplan og vær": "Statybvietės planavimas: reljefas, įrengimas, betonavimo planas, darbų grafikas ir orai",
  "Priskalkulasjon: mengder × priser til Excel": "Kainų skaičiavimas: kiekiai × kainos į Excel",
  "Priskalkulasjon: kilde, lagring og Excel": "Kainų skaičiavimas: šaltinis, išsaugojimas ir Excel",
  "Priskalkulasjon (i Bygg Info) lager en kalkyle av mengdene i modellen. Legg til poster Fra modellen (objekttype og materiale, som i Mengder), med Marker i modellen (trykk på det som skal med og så Ferdig) eller som Egen linje. Velg enhet — m³, m², lm, stk eller kg — og fyll inn enhetspris og påslag. Objekter med flere materialer, som et gulv med betong og isolasjon, blir én post per materiale. Øyet viser postens objekter i 3D.": "Kainų skaičiavimas (Pastato info) sudaro sąmatą iš modelio kiekių. Pridėkite eilutes Iš modelio (objekto tipas ir medžiaga, kaip Kiekiuose), per Pažymėti modelyje (spustelėkite, ką įtraukti, tada Baigta) arba kaip Savą eilutę. Pasirinkite vienetą — m³, m², m, vnt. ar kg — ir įveskite vieneto kainą bei antkainį. Objektai su keliomis medžiagomis, pvz., grindys su betonu ir izoliacija, tampa atskira eilute kiekvienai medžiagai. Akis rodo eilutės objektus 3D.",
  "Kilde velger om mengden kommer fra 3D-geometrien eller fra tallene prosjekterende har lagt i IFC-fila; Geometri / fila viser begge og avviket i farger. Prisene lagres bare i SharePoint, én liste per prosjektnummer (Innstillinger → Prosjektinfo) — er du ikke logget inn, lagres de ikke. Last ned Excel gir kalkylen med formler og ferdige summer, et kontrollark som viser hvordan hvert tall er regnet, og alle elementene per post.": "Šaltinis nurodo, ar kiekis imamas iš 3D geometrijos, ar iš projektuotojo IFC faile įrašytų skaičių; Geometrija / failas rodo abu ir nuokrypį spalvomis. Kainos saugomos tik SharePoint, vienas sąrašas projekto numeriui (Nustatymai → Projekto informacija) — neprisijungus jos neišsaugomos. Atsisiųsti Excel pateikia sąmatą su formulėmis ir paruoštomis sumomis, patikros lapą, rodantį, kaip apskaičiuotas kiekvienas skaičius, ir visus elementus pagal eilutę.",
  "Slik er mengden regnet": "Kaip apskaičiuotas kiekis",
  "Utregning av linjesum": "Eilutės sumos skaičiavimas",
  "Elementer per post": "Elementai pagal eilutę",
