  "Antall objekter i posten ({0} stk).": "Objektų skaičius eilutėje ({0} vnt.).",
  "Tallet «{0}» fra IFC-fila for {1} av {2} elementer; resten fra 3D-geometrien. Summert.": "Reikšmė „{0}“ iš IFC failo {1} iš {2} elementų; likusieji – iš 3D geometrijos. Susumuota.",
  "Volumet av hvert element, målt i 3D-geometrien (SW, gulv og materiell: lengde × høyde/bredde × tykkelse). Lagdelte elementer: volumet fordelt etter lagtykkelse.": "Kiekvieno elemento tūris, išmatuotas 3D geometrijoje (SW, grindys ir medžiagos: ilgis × aukštis/plotis × storis). Sluoksniuoti elementai: tūris padalytas pagal sluoksnių storį.",
  "Største flate per element (veggside, dekkets overside, plate L × B). Summert.": "Didžiausias elemento paviršius (sienos šonas, perdangos viršus, lakštas I × P). Susumuota.",
  "Lengden av hvert element (lengste mål). Summert.": "Kiekvieno elemento ilgis (ilgiausias matmuo). Susumuota.",
  "Stål: kg/m fra profiltabellen × lengde. Ellers volum × tetthet (betong 2400, stål 7850 kg/m³). Summert.": "Plienas: kg/m iš profilių lentelės × ilgis. Kitaip tūris × tankis (betonas 2400, plienas 7850 kg/m³). Susumuota.",
