  "Dagsrapport ligger i Rapport-menyen (Dokumentasjon), bare på kontorsiden. Uke-stripa viser hvilke dager som er levert, hvilke som er utkast og hvilke arbeidsdager som mangler (rødt). Været fylles inn av seg selv fra adressen i Prosjektinfo. Du fyller ut bemanning (firma, fag, antall, timer), utført arbeid og hindringer og avvik, og kan legge ved bilder. «Samme som sist» henter bemanningen fra forrige rapport. Signer og lag PDF låser rapporten og legger PDF-en i SharePoint. Ny versjon lager en kopi du kan endre, og den signerte blir liggende. Hele uka som PDF gir en forside med uka i tall og avvik, og så hver dag.": "Dienos ataskaita yra meniu Ataskaita (Dokumentacija), tik biuro puslapyje. Savaitės juosta rodo, kurios dienos pateiktos, kurios yra juodraščiai ir kurių darbo dienų trūksta (raudonai). Orai užpildomi automatiškai pagal adresą Projekto informacijoje. Užpildote darbuotojus (įmonė, specialybė, skaičius, valandos), atliktus darbus bei kliūtis ir nukrypimus, galite pridėti nuotraukų. «Kaip praėjusį kartą» nukopijuoja darbuotojus iš ankstesnės ataskaitos. Pasirašyti ir sukurti PDF užrakina ataskaitą ir įdeda PDF į SharePoint. Nauja versija sukuria kopiją, kurią galite keisti, o pasirašyta lieka. Visa savaitė PDF pateikia titulinį puslapį su savaitės skaičiais ir nukrypimais, o po to kiekvieną dieną.",
  // 🧅 Lag (runde 5a, 28.10.2026)
