  "Posisjonsnummer finnes ikke i IFC-fila. «Marker alle like» bruker diameter og bøyeform.": "IFC faile nėra pozicijos numerio. «Pažymėti visus vienodus» naudoja skersmenį ir lenkimo formą.",
