  "Fra disk …": "Iš disko …",
  "IFC gjøres om i bakgrunnen. Hovedmodellen blir liggende. Ferdige lag lagres i SharePoint og åpnes raskt neste gang.": "IFC konvertuojamas fone. Pagrindinis modelis lieka atidarytas. Paruošti sluoksniai išsaugomi SharePoint ir kitą kartą atsidaro greitai.",
  "Hovedmodell · alle verktøy": "Pagrindinis modelis · visi įrankiai",
  "Ingen lag ennå. Legg til armering, stål eller en annen fagmodell oppå hovedmodellen.": "Sluoksnių dar nėra. Pridėkite armatūrą, plieną ar kitą specialybės modelį ant pagrindinio modelio.",
