  "Lag: modeller oppå hovedmodellen": "Sluoksniai: modeliai ant pagrindinio modelio",
  "Lag (i Bygg Info) legger armering, stål eller andre fagmodeller oppå hovedmodellen. Velg en IFC fra biblioteket eller disken og trykk Legg til — eller dra fila rett inn i den stiplede ruta. IFC-en gjøres om i bakgrunnen mens hovedmodellen blir liggende. Kortet viser antall, vekt og dimensjoner; for armering regnes vekten ut fra diameter, lengde og antall stenger. Trykk på et element i laget for nøkkeltall, Bare dette laget eller Skjul dette laget. Lagene kan også skjules under Farger i Visning. Ferdige lag lagres i SharePoint og åpnes raskt neste gang.": "Sluoksniai (Pastato informacijoje) uždeda armatūrą, plieną ar kitus specialybių modelius ant pagrindinio modelio. Pasirinkite IFC iš bibliotekos ar disko ir spauskite Pridėti — arba įtempkite failą tiesiai į punktyrinį langelį. IFC konvertuojamas fone, o pagrindinis modelis lieka atidarytas. Kortelėje rodomas kiekis, svoris ir skersmenys; armatūros svoris apskaičiuojamas pagal skersmenį, ilgį ir strypų skaičių. Spustelėkite sluoksnio elementą, kad pamatytumėte pagrindinius duomenis, Tik šis sluoksnis arba Slėpti šį sluoksnį. Sluoksnius taip pat galima paslėpti skiltyje Spalvos (Rodinys). Paruošti sluoksniai išsaugomi SharePoint ir kitą kartą atsidaro greitai.",
  "Lag vist": "Sluoksnis rodomas",
  "Lag skjult": "Sluoksnis paslėptas",
  "Skjul dette laget": "Slėpti šį sluoksnį",
  "Slipp IFC her for å legge den til som lag": "Numeskite IFC čia, kad pridėtumėte kaip sluoksnį",
  "Slipp en .ifc- eller .glb-fil.": "Numeskite .ifc arba .glb failą.",
  "Hovedmodellen er en lett kopi uten plassering (laget før 28.10.2026). Lag den lette kopien på nytt, eller åpne IFC-en, så havner lagene riktig.": "Pagrindinis modelis yra lengva kopija be padėties (sukurta iki 2026-10-28). Sukurkite lengvą kopiją iš naujo arba atidarykite IFC, kad sluoksniai atsidurtų teisingoje vietoje.",
  "«{0}» er laget før 28.10.2026 og mangler plassering. Legg til IFC-en i stedet, så havner laget riktig.": "«{0}» sukurtas iki 2026-10-28 ir neturi padėties. Pridėkite IFC, kad sluoksnis atsidurtų teisingoje vietoje.",
  "Juster plassering": "Koreguoti padėtį",
