  "Leser etasjene …": "Skaitomi aukštai …",
  "Hovedmodellen er en lett kopi uten etasjehøyder. Lag den lette kopien på nytt, eller åpne IFC-en.": "Pagrindinis modelis yra lengva kopija be aukštų aukščių. Sukurkite lengvą kopiją iš naujo arba atidarykite IFC.",
  "Laget har ingen etasjer i IFC-en. Bruk midtpunkt og tastene.": "Sluoksnis IFC faile neturi aukštų. Naudokite vidurio tašką ir klavišus.",
  "Fant ingen etasjer med samme navn i hovedmodellen og laget.": "Pagrindiniame modelyje ir sluoksnyje nerasta aukštų tuo pačiu pavadinimu.",
  "Avviker: {0}. Kontroller før du justerer.": "Skiriasi: {0}. Patikrinkite prieš koreguodami.",
  "Høyde fra etasjer: {0} stemmer (0 mm).": "Aukštis pagal aukštus: {0} sutampa (0 mm).",
