  "{0} ligger {1} mm lavere i laget.": "{0} sluoksnyje yra {1} mm žemiau.",
  "Høyde fra etasjer:": "Aukštis pagal aukštus:",
  "Høyden er justert etter etasjene.": "Aukštis pakoreguotas pagal aukštus.",
