  "JUSTER PLASSERING": "KOREGUOTI PADĖTĮ",
  "1/2: Klikk en søyle eller pæl i hovedmodellen.": "1/2: Spustelėkite koloną arba polį pagrindiniame modelyje.",
  "2/2: Klikk den samme søylen eller pælen i laget.": "2/2: Spustelėkite tą pačią koloną arba polį sluoksnyje.",
  "Sideveis: klikk en søyle/pæl i hovedmodellen, så den samme i laget. Midtpunktene sett ovenfra legges oppå hverandre.": "Į šonus: spustelėkite koloną/polį pagrindiniame modelyje, tada tą patį sluoksnyje. Vidurio taškai, žiūrint iš viršaus, sutapdinami.",
  "Midtpunkt …": "Vidurio taškas …",
  "Øst (mm)": "Rytai (mm)",
  "Nord (mm)": "Šiaurė (mm)",
  "Høyde (mm)": "Aukštis (mm)",
  "Ferdig (Esc)": "Baigta (Esc)",
  "Flytt med tastene": "Perkelti klavišais",
  "vest/øst": "vakarai/rytai",
  "nord/sør": "šiaurė/pietūs",
  "rull fram = opp": "slinkti pirmyn = aukštyn",
  "rull bak = ned": "slinkti atgal = žemyn",
  "Med «Flytt med tastene» på styrer piltastene, Z/X og rullehjulet laget i stedet for kameraet.": "Įjungus «Perkelti klavišais», rodyklės, Z/X ir ratukas valdo sluoksnį, o ne kamerą.",
  "Høyde justert etter etasjene": "Aukštis pakoreguotas pagal aukštus",
  "Lagets justering nullstilt": "Sluoksnio korekcija atstatyta",
  "Klikk en søyle eller pæl i hovedmodellen.": "Spustelėkite koloną arba polį pagrindiniame modelyje.",
  "Traff ikke noe i hovedmodellen. Klikk en søyle eller pæl.": "Pagrindiniame modelyje nieko nepataikyta. Spustelėkite koloną arba polį.",
  "Klikk den samme søylen eller pælen i laget «{0}».": "Spustelėkite tą pačią koloną arba polį sluoksnyje «{0}».",
  "Traff ikke noe i laget «{0}». Klikk den samme søylen eller pælen der.": "Sluoksnyje «{0}» nieko nepataikyta. Spustelėkite ten tą pačią koloną arba polį.",
  "Laget flyttet etter midtpunkt": "Sluoksnis perkeltas pagal vidurio tašką",
  "Midtpunktene lagt oppå hverandre: Øst {0} mm, Nord {1} mm.": "Vidurio taškai sutapdinti: rytai {0} mm, šiaurė {1} mm.",
  "Flytt laget med piltastene, Z/X eller rullehjulet. Esc = ferdig.": "Perkelkite sluoksnį rodyklėmis, Z/X arba ratuku. Esc = baigta.",
  "Laget flyttet med tastene": "Sluoksnis perkeltas klavišais",
  "«{0}»: lagret justering brukt ({1}).": "«{0}»: pritaikyta išsaugota korekcija ({1}).",
  "etasjer": "aukštai",
  "midtpunkt": "vidurio taškas",
  "manuelt": "rankiniu būdu",
  "Lag: juster plassering": "Sluoksniai: koreguoti padėtį",
  "Ligger et lag litt feil oppå hovedmodellen, trykker du Juster plassering på kortet. Høyde fra etasjer sammenligner etasjene med samme navn og foreslår hvor mye laget skal flyttes opp eller ned (for eksempel −120 mm). Midtpunkt: klikk en søyle eller pæl i hovedmodellen og så den samme i laget, så legges midtpunktene sett ovenfra oppå hverandre. Flytt med tastene: piltastene flytter øst, vest, nord og sør, Z eller rullehjulet fram flytter opp, X eller rullehjulet bak flytter ned. Velg 1, 10 eller 100 mm per trykk, Shift gir 1 mm. Esc avslutter, og hele flyttingen kan angres med Ctrl+Z. Nullstill går tilbake til plasseringen fra Revit. Justeringen lagres og brukes igjen neste gang samme lag legges på samme hovedmodell.": "Jei sluoksnis ant pagrindinio modelio guli šiek tiek netiksliai, kortelėje paspauskite Koreguoti padėtį. Aukštis pagal aukštus palygina tuo pačiu pavadinimu pavadintus aukštus ir pasiūlo, kiek sluoksnį perkelti aukštyn ar žemyn (pavyzdžiui, −120 mm). Vidurio taškas: spustelėkite koloną arba polį pagrindiniame modelyje, tada tą patį sluoksnyje, ir vidurio taškai, žiūrint iš viršaus, sutapdinami. Perkelti klavišais: rodyklės perkelia į rytus, vakarus, šiaurę ir pietus, Z arba ratukas pirmyn – aukštyn, X arba ratukas atgal – žemyn. Pasirinkite 1, 10 arba 100 mm vienam paspaudimui, Shift duoda 1 mm. Esc baigia, o visą perkėlimą galima atšaukti Ctrl+Z. Atstatyti grąžina į padėtį iš Revit. Korekcija išsaugoma ir vėl naudojama kitą kartą, kai tas pats sluoksnis pridedamas prie to paties pagrindinio modelio.",
  "Midtpunktene ligger {0} mm fra hverandre. Er det samme søyle eller pæl i begge? Flytt likevel?": "Vidurio taškus skiria {0} mm. Ar tai ta pati kolona arba polis abiejuose? Vis tiek perkelti?",
  "«{0}» finnes ikke i SharePoint. Legg laget til på nytt mens du er logget inn, og lagre gruppen igjen.": "«{0}» nėra SharePoint. Pridėkite sluoksnį iš naujo prisijungę ir vėl išsaugokite grupę.",
  "«{0}» ligger ikke i biblioteket og kan ikke åpnes som hovedmodell herfra.": "«{0}» nėra bibliotekoje ir negali būti atidarytas kaip pagrindinis modelis iš čia.",
