  "Lag: modellgruppe og mengder per lag": "Sluoksniai: modelių grupė ir kiekiai pagal sluoksnį",
  "Øverst i Lag-panelet kan du lagre det som er åpent som en modellgruppe: hovedmodellen og lagene med farge, gjennomsiktighet og justering. Velg gruppen i lista og trykk Åpne, så åpnes alt med ett trykk, også på en annen PC. Gruppene og lagene lagres i SharePoint, så du må være logget inn. Står det «Ikke lagret — logg inn på SharePoint» med rødt på et lag-kort, er laget ikke lagret ennå; det lagres av seg selv når du logger inn. Mengder per lag (under kortene) viser hver type (som i Mengder) og armeringen per diameter med stenger, løpemeter og vekt. Velg enhet per rad (lm, m², m³, stk eller kg): isolasjon står i m² og betong i m³ fra start, og valget huskes. Armeringen telles slik også når den er åpnet som hovedmodell (IFC). Excel-knappen lager ett ark per lag, et sammendrag og et ark per bøyeform for armeringen.": "Sluoksnių skydelio viršuje galite išsaugoti tai, kas atidaryta, kaip modelių grupę: pagrindinį modelį ir sluoksnius su spalva, skaidrumu ir korekcija. Pasirinkite grupę sąraše ir paspauskite Atidaryti – viskas atsidarys vienu paspaudimu, taip pat kitame kompiuteryje. Grupės ir sluoksniai išsaugomi SharePoint, todėl turite būti prisijungę. Jei sluoksnio kortelėje raudonai parašyta «Neišsaugota — prisijunkite prie SharePoint», sluoksnis dar neišsaugotas; jis išsisaugos pats, kai prisijungsite. Kiekiai pagal sluoksnį (po kortelėmis) rodo kiekvieną tipą (kaip Kiekiuose) ir armatūrą pagal skersmenį su strypais, tekančiaisiais metrais ir svoriu. Pasirinkite vienetą kiekvienai eilutei (lm, m², m³, vnt. arba kg): izoliacija pradžioje rodoma m², betonas m³, o pasirinkimas įsimenamas. Armatūra taip skaičiuojama ir tada, kai ji atidaryta kaip pagrindinis modelis (IFC). Excel mygtukas sukuria po vieną lapą kiekvienam sluoksniui, santrauką ir lapą pagal lenkimo formą armatūrai.",
  "{0} bøyeformer — se arket «Per bøyeform» i Excel.": "{0} lenkimo formos — žr. lapą «Pagal lenkimo formą» Excel faile.",
  "Hovedmodellen er en lett kopi: armeringen telles som Revit-sett, uten diameter og vekt. Åpne IFC-en for stenger og vekt.": "Pagrindinis modelis yra lengva kopija: armatūra skaičiuojama kaip Revit rinkiniai, be skersmens ir svorio. Atidarykite IFC strypams ir svoriui.",
  "Per bøyeform": "Pagal lenkimo formą",
