  "hovedmodellen": "pagrindiniu modeliu",
  "Ingen lag å kontrollere. Legg til armering, stål eller en annen fagmodell i Lag-panelet først.": "Nėra sluoksnių tikrinti. Pirmiausia pridėkite armatūrą, plieną ar kitą modelį Sluoksnių skydelyje.",
