  "Utenfor betongen": "Už betono ribų",
  "Overdekning": "Apsauginis sluoksnis",
  "Kollisjon: finn armering utenfor betongen og stål som går inn i betongen": "Kolizija: raskite armatūrą už betono ir plieną, įsiskverbiantį į betoną",
  "Kollisjon: armering utenfor betongen og stål som går inn": "Kolizija: armatūra už betono ir plienas, kuris įsiskverbia",
  "Fanen Kollisjon i Lag-panelet (den kommer når et lag er lagt til) kontrollerer hvert lag mot hovedmodellen. Armering mot betong: finner armering som stikker utenfor betongen, og for liten overdekning hvis du skriver inn kravet fra RIB (tomt felt = ikke kontrollert). Stål, rør og andre lag: finner det som går inn i betongen (å ligge an mot er i orden). Trykk Kjør kontroll. Pilene nederst går gjennom funnene ett og ett og zoomer dit. Godkjenn det som er riktig (for eksempel oppstikk til neste støp) med en kort begrunnelse, eller lag en markering. Status (Ny, Godkjent, Løst) lagres i SharePoint, så neste kjøring viser bare det som er nytt — og det RIB har rettet, blir Løst av seg selv. BCF og Excel lages fra lista.": "Skirtukas Kolizija Sluoksnių skydelyje (atsiranda pridėjus sluoksnį) tikrina kiekvieną sluoksnį su pagrindiniu modeliu. Armatūra su betonu: randa armatūrą, išlindusią už betono, ir per mažą apsauginį sluoksnį, jei įvedate konstruktoriaus reikalavimą (tuščias laukas = netikrinama). Plienas, vamzdžiai ir kiti sluoksniai: randa tai, kas įsiskverbia į betoną (atsirėmimas yra tvarkoje). Paspauskite Vykdyti patikrą. Rodyklės apačioje eina per radinius po vieną ir priartina. Patvirtinkite tai, kas teisinga (pvz., išleidimus kitam betonavimui), su trumpu paaiškinimu arba sukurkite žymę. Būsena (Nauja, Patvirtinta, Išspręsta) išsaugoma SharePoint, todėl kitas paleidimas rodo tik naujus – o tai, ką konstruktorius ištaisė, tampa Išspręsta savaime. BCF ir Excel daromi iš sąrašo.",
  "{0} betongelementer har ufullstendig geometri i IFC-fila og er kontrollert med boksen rundt (grovere, og uten overdekning).": "{0} betoniniai elementai IFC faile turi nepilną geometriją ir tikrinami pagal gaubiančią dėžę (apytiksliai, be apsauginio sluoksnio).",
