  "Kapasiteten er «Maks last ytterst på bommen» i kranens felt over, helt ut til svingradius = bomlengde (på den sikre siden).": "Galia yra «Didž. apkrova strėlės gale» krano laukuose aukščiau, iki pat sukimosi spindulio = strėlės ilgio (saugiau).",
  "Skriv inn «Maks last ytterst på bommen» i kranens felt over for å sjekke løftene.": "Įrašykite «Didž. apkrova strėlės gale» krano laukuose aukščiau, kad patikrintumėte kėlimus.",
