  "Sjekkliste før støp per etappe": "Patikros sąrašas prieš betonavimą kiekvienam etapui",
  "Hver etappe i Støpeplan har en sjekkliste «Før støp». Trykk «Start sjekkliste» på etappekortet, og huk av punktene etter hvert — det står hvem som huket av og når. Når alt er huket av, signerer du med fingeren eller musa (samme signaturboks som Dagsrapport). Først da kan etappen settes «Klar til støp». Tas et punkt av etterpå, faller signaturen og «klar» bort. PDF-knappen gir sjekklista med signatur. Punktene er forslag: vil dere ha egne, legg malen for-stop.json i SharePoint-mappa Sjekklister og endre den der. På byggeplass-siden kan basen huke av, ta bilde av punktet og signere med fingeren på telefonen. Det kommer inn her (med 📱 og 📷) når du trykker Storm-Byggeplass, og Teams får beskjed når lista er ferdig huket av og når den er signert.": "Kiekvienas betonavimo plano etapas turi sąrašą «Prieš betonavimą». Etapo kortelėje paspauskite «Pradėti sąrašą» ir žymėkite punktus — matyti, kas ir kada pažymėjo. Kai viskas pažymėta, pasirašykite pirštu arba pele (tas pats parašo langas kaip Dienos ataskaitoje). Tik tada etapą galima pažymėti «Paruošta betonuoti». Jei vėliau punktas atžymimas, parašas ir «paruošta» panaikinami. PDF mygtukas pateikia sąrašą su parašu. Punktai yra pasiūlymai: norėdami savų, įdėkite šabloną for-stop.json į SharePoint aplanką Sjekklister ir redaguokite ten. Statybvietės puslapyje meistras gali žymėti punktus, nufotografuoti punktą ir pasirašyti pirštu telefone. Tai atsiranda čia (su 📱 ir 📷), kai paspaudžiate Storm-Byggeplass, o Teams gauna pranešimą, kai sąrašas visiškai pažymėtas ir kai jis pasirašytas.",
  "Løfteplan: klarer kranen løftene?": "Kėlimo planas: ar kranas pakels?",
  "Løfteplanen ligger inni tårnkranen i Rigg (trykk på kranen), og Dokumentasjon → Løfteplan går rett dit. Skriv inn «Maks last ytterst på bommen» i kranens felt, ved siden av svingradius = bomlengde. Den lasten brukes helt ut til bommens ende, så du er på den sikre siden. Legg til vekten av løfteutstyret (åk, stropper), og velg om radius skal måles til midten av elementet eller til hjørnet lengst unna. Huk av hvilke materialgrupper kranen løfter — plasstøpt betong løftes ikke, så Betong er av til du slår den på for betongelementer. Materiell (bunkene) er et eget punkt: skriv vekten på bunken rett i lista, så sjekkes også den. Vekten tas fra Mengder. Modellen og Excel-arket farges likt: grønn under 80 % av kapasiteten, gul 80–99 %, rød 100 % eller mer, grå når vekten er ukjent eller elementet er utenfor lastkurven. Trykk på en rad for å gå til elementet. Excel gir hele lista og kranens tall, og de røde kan bli markeringer. Maks last må komme fra kranleverandørens datablad.": "Kėlimo planas yra bokštiniame krane skiltyje Statybvietė (paspauskite kraną), o Dokumentacija → Kėlimo planas veda tiesiai ten. Įrašykite «Didž. apkrova strėlės gale» krano laukuose, šalia sukimosi spindulio = strėlės ilgio. Ši apkrova naudojama iki pat strėlės galo, todėl esate saugioje pusėje. Pridėkite kėlimo įrangos (traversos, stropų) svorį ir pasirinkite, ar spindulį matuoti iki elemento vidurio, ar iki tolimiausio kampo. Pažymėkite, kurias medžiagų grupes kelia kranas — monolitinis betonas nekeliamas, todėl Betonas išjungtas, kol neįjungsite jo surenkamiems elementams. Medžiagos (rietuvės) yra atskiras punktas: įrašykite rietuvės svorį tiesiai sąraše, ir ji taip pat bus patikrinta. Svoris imamas iš Kiekių. Modelis ir Excel lapas spalvinami vienodai: žalia — mažiau nei 80 % galios, geltona 80–99 %, raudona — 100 % ar daugiau, pilka — kai svoris nežinomas arba elementas už kreivės ribų. Paspauskite eilutę, kad pereitumėte prie elemento. Excel pateikia visą sąrašą ir krano duomenis, o raudoni gali tapti žymėmis. Didž. apkrova turi būti iš krano tiekėjo duomenų lapo.",
  "Løfteplan: kransjekk av løftene (åpner kranen i Rigg)": "Kėlimo planas: krano patikra (atidaro kraną skiltyje Statybvietė)",
