  "FDV-bibliotek og varer uten 3D": "FDV biblioteka ir prekės be 3D",
  "Hver FDV-gruppe du lager, havner av seg selv i FDV-biblioteket (fanen Bibliotek i FDV-panelet) — med PDF-ene og Revit-typene du koblet. Åpner du et nytt prosjekt med de samme typene, foreslår Storm varen i en gul boks: trykk Bruk, så kommer PDF-ene og objektene inn med en gang. I Bibliotek-fanen kan du søke og hente en vare selv. Tar du en hel type ut av en gruppe, glemmer biblioteket den koblingen. Varer som ikke finnes i modellen (skruer, byggeskum, spiker) skriver du inn under «Varer uten 3D-modell» i gruppa, med mengde og enhet — eller lag en «Ny vare uten PDF» og legg PDF-en på senere. De kommer med i status (raden Uten 3D) og i FDV-pakken.": "Kiekviena sukurta FDV grupė automatiškai patenka į FDV biblioteką (FDV skydelio skirtukas Biblioteka) — su PDF ir susietais Revit tipais. Atidarius naują projektą su tais pačiais tipais, Storm pasiūlo prekę geltoname langelyje: paspauskite Naudoti, ir PDF bei objektai įtraukiami iš karto. Skirtuke Biblioteka galite patys ieškoti ir paimti prekę. Jei iš grupės pašalinate visą tipą, biblioteka pamiršta šį ryšį. Prekes, kurių nėra modelyje (varžtai, montavimo putos, vinys), įrašote grupėje skiltyje «Prekės be 3D modelio», su kiekiu ir vienetu — arba sukurkite «Nauja prekė be PDF» ir PDF pridėkite vėliau. Jos įtraukiamos į būseną (eilutė Be 3D) ir į FDV paketą.",
