  "Biblioteket er tomt. Hver FDV-gruppe du lager i et prosjekt, havner her av seg selv — med PDF-ene og Revit-typene.": "Biblioteka tuščia. Kiekviena projekte sukurta FDV grupė čia patenka automatiškai — su PDF ir Revit tipais.",
