  "Biblioteket ligger i SharePoint (FDV/_bibliotek.fdv.json) og er felles for alle prosjekter. En PDF lagt på en vare i ett prosjekt, kommer med i de andre prosjektene som bruker varen.": "Biblioteka saugoma SharePoint (FDV/_bibliotek.fdv.json) ir bendra visiems projektams. PDF, pridėtas prie prekės viename projekte, atsiranda ir kituose projektuose, naudojančiuose prekę.",
