  "Slette FDV-gruppa «{0}»? Objektene blir røde igjen. PDF-ene blir liggende i SharePoint.": "Ištrinti eksploatacijos grupę «{0}»? Objektai vėl taps raudoni. PDF liks SharePoint.",
